<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { TabBarContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
import {tabBarPaths} from './tab-bar-icons.js';let p: TabBarContract & {icons?:Readonly<Record<string,Snippet>>} = $props();const uid=$props.id();function validate(){for(const item of p.items)for(const icon of[item.icon,item.currentIcon].filter(Boolean))if(icon&&!Object.hasOwn(tabBarPaths,icon)&&!p.icons?.[icon])throw new TypeError(`Unknown TabBar icon: ${icon}; supply a native icons snippet`);}validate();$effect(validate);$effect(()=>{if(p.items.length+(p.menuAction?1:0)>5)throw new RangeError('Tab bar supports at most five items');});

</script>
<nav {...owned('tab-bar','root')} aria-label="주요 화면"><ul {...owned('tab-bar','list')}>{#each p.items as item(item.id)}{@const icon=p.currentId===item.id?(item.currentIcon??item.icon):item.icon}<li {...owned('tab-bar','item',p.currentId===item.id&&'current')}><a {...owned('tab-bar','link')} href={item.href} aria-current={p.currentId===item.id?'page':undefined}>{#if p.currentId===item.id}<span {...owned('tab-bar','indicator')} aria-hidden="true">•</span>{/if}<span {...owned('tab-bar','icon')} aria-hidden="true">{#if p.icons?.[icon]}{@render p.icons[icon]()}{:else}<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" tabindex="-1" aria-hidden="true"><path d={tabBarPaths[icon as keyof typeof tabBarPaths]}/></svg>{/if}</span><span {...owned('tab-bar','label')}>{item.label}</span>{#if item.badge!==undefined}<span {...owned('tab-bar','badge')}>{item.badge}</span>{/if}</a></li>{/each}{#if p.menuAction}<li><button type="button" {...owned('tab-bar','menu-trigger')} onclick={()=>p.menuAction?.onRequest()}>{p.menuAction.label}</button></li>{/if}</ul></nav>
